-- 旧品牌图片：定位超过新上限的字段；只返回机构ID及字节数。由超管重新上传压缩图；不在SQL中自动压缩。
SELECT tenant_id,length(CAST(logo AS BLOB)) logo_bytes,length(CAST(login_bg AS BLOB)) login_bg_bytes,length(CAST(consultant_qr AS BLOB)) qr_bytes FROM tenant_branding WHERE length(CAST(logo AS BLOB))>260000 OR length(CAST(login_bg AS BLOB))>260000 OR length(CAST(consultant_qr AS BLOB))>260000;
